<div class="admin-panel other-income-filters"><form class="other-income-filter-bar" method="get"><input type="hidden" name="page" value="admin"><input type="hidden" name="section" value="other-income"><label>Search<input class="form-control" name="search" value="<?= e($filters['search']) ?>" placeholder="Search title, category or reference..."></label><label>Category<select class="form-select" name="category"><option value="">All categories</option><?php foreach ($categories as $category): ?><option value="<?= e((string) $category) ?>" <?= $filters['category'] === $category ? 'selected' : '' ?>><?= e((string) $category) ?></option><?php endforeach; ?></select></label><label>Payment Method<select class="form-select" name="payment_method"><option value="">All methods</option><?php foreach ($paymentLabels as $value => $label): ?><option value="<?= e($value) ?>" <?= $filters['payment_method'] === $value ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><label>From Date<input class="form-control" type="date" name="from" value="<?= e($filters['from']) ?>"></label><label>To Date<input class="form-control" type="date" name="to" value="<?= e($filters['to']) ?>"></label><div class="other-income-filter-actions"><button class="btn btn-primary" type="submit">Filter</button><a class="btn btn-light" href="index.php?page=admin&amp;section=other-income">Reset</a></div></form></div>
<div class="admin-panel other-income-list"><div class="panel-heading"><h2>Income Records</h2><span class="text-muted"><?= $summary['records'] ?> records</span></div><div class="table-responsive"><table class="table admin-table other-income-table"><thead><tr><th>Date</th><th>Income Type</th><th>Category</th><th>Reference</th><th>Payment Method</th><th>Amount (Rs.)</th><th>Added By</th><th>Actions</th></tr></thead><tbody><?php if (!$rows): ?><tr><td colspan="8" class="empty-table">No other income records found. Click Add Other Income to create the first record.</td></tr><?php else: foreach ($rows as $row): ?><tr><td><?= e($row['income_date']) ?></td><td><strong><?= e($row['title']) ?></strong><?php if ($row['notes']): ?><small class="d-block text-muted"><?= e($row['notes']) ?></small><?php endif; ?></td><td><?= e($row['category'] ?: '-') ?></td><td><?= e($row['reference_no'] ?: '-') ?></td><td><span class="income-method income-method-<?= e($row['payment_method']) ?>"><?= e($paymentLabels[$row['payment_method']] ?? ucfirst($row['payment_method'])) ?></span></td><td><strong><?= number_format((float) $row['amount'], 2) ?></strong></td><td><?= e($row['created_by_name'] ?: '-') ?></td><td><div class="action-links employee-actions"><a href="index.php?page=admin&amp;section=other-income-view&amp;id=<?= (int) $row['id'] ?>" title="View income" aria-label="View income">&#128065;</a><a href="index.php?page=admin&amp;section=other-income-edit&amp;id=<?= (int) $row['id'] ?>" title="Edit income" aria-label="Edit income">&#9998;</a><form method="post" action="index.php?page=admin&amp;section=other-income-delete" onsubmit="return confirm('Delete this other income record?');"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="income_id" value="<?= (int) $row['id'] ?>"><button type="submit" title="Delete income" aria-label="Delete income">&#128465;</button></form></div></td></tr><?php endforeach; endif; ?></tbody></table></div></div>
